from author import *
begin("exclusions")
C("A fallback field is exactly four lowercase ASCII letters, except the exact word null. No spaces or other characters.",r"(?!null$)[a-z]{4}","aaaa|zzzz|abcd|wxyz|word|text|line|name","null|abc|abcde|Abcd|abc1|ab_c|a bc", "A reserved word is an exact exclusion, not a substring ban.")
C("A badge is exactly six ASCII digits except all zeros. Leading zeros are otherwise permitted.",r"(?!000000$)[0-9]{6}","000001|999999|123456|654321|100000|010000|001000|000100","000000|00000|0000000|12345a|１２３４５６|12 456|+12345", "Reject only the zero sentinel, not every zero-leading code.")
C("A directory label is exactly five lowercase ASCII letters and must not start with tmp. No other characters.",r"(?!tmp)[a-z]{5}","aaaaa|zzzzz|abcde|wxyza|tmabc|atmpa|tmapa|cache","tmpab|tmper|abcd|abcdef|Abcde|abc1e|ab_cd", "Only the initial substring is forbidden.")
C("The token is exactly eight uppercase ASCII letters, with no letter I or O anywhere. Nothing else.",r"[A-HJ-NP-Z]{8}","AAAAAAAA|ZZZZZZZZ|ABCDEFGH|JKLMNPQR|QWERTYAS|ZXCVBNMA|HHHHHHHH|XYZABCDE","IAAAAAAA|AAAAAAAO|AAAAIAA A|AAAAAAA|AAAAAAAAA|aaaaaaaa|AAAAAAA1", "An excluded alphabet applies to every position.")
C("A suffix key is exactly six lowercase ASCII letters, except it must not end in log. No spaces or other characters.",r"(?![a-z]{3}log$)[a-z]{6}","aaaaaa|zzzzzz|abcdef|logabc|abclox|logger|fooabc|xyzzzz","abclog|xyzlog|loglog|abcde|abcdefg|ABCDEF|abcde1", "The ban is on the final three letters, not any occurrence.")
C("A lowercase ASCII login has 6 to 12 letters, may not be exactly admins or system, and may not contain the substring test anywhere. No digits or punctuation.",r"(?!admins$|system$)(?!.*test)[a-z]{6,12}","abcdef|abcdefghijkl|adminsx|systems|tesabc|tsetab|public|secret","system|admins|abtestcd|testing|abcde|abcdefghijklm|ABCDEF|abcde1", "Exact reserved names and an internal substring ban are different rules.")
C("A code is exactly eight ASCII letters or digits, includes at least one of each, and neither starts nor ends with a digit. The substring bad is forbidden in any ASCII letter case.",r"(?=[A-Za-z0-9]{8}$)(?=.*[0-9])(?!.*bad)[A-Za-z][A-Za-z0-9]*[A-Za-z]","a000000b|A1bcdefZ|abc123de|foo42bar|X999999Y|good123a|q1w2e3rt|z000000z","abcdefgh|1abcdefg|abcdefg1|aBAD12bc|xxbad12x|a00000b|a0000000b|abc_12de", "Case-insensitive substring bans need not change the allowed alphabet.","i")
C("A file label has 3 to 12 lowercase ASCII letters or digits, begins with a letter, and may contain internal single hyphens. It must not start with tmp- or end with -old. Count hyphens toward length; no adjacent or edge hyphens.",r"(?=.{3,12}$)(?!tmp-)(?!.*-old$)[a-z][a-z0-9]*(?:-[a-z0-9]+)*","abc|a-b|tmpx-a|a-oldx|abcdefghijkl|file-1|old-file|tm-p","tmp-abc|abc-old|ab|abcdefghijklm|1abc|abc-|ab--c|Abc", "Prefix and suffix bans are narrower than banning their words everywhere.")
C("A booking slot is slot- plus a canonical integer 1 through 64, except 13 and 42 are reserved. No padding or spaces.",r"slot-(?!13$|42$)(?:[1-9]|[1-5][0-9]|6[0-4])","slot-1|slot-64|slot-12|slot-14|slot-41|slot-43|slot-9|slot-10","slot-13|slot-42|slot-0|slot-65|slot-01|slot-+1|slot-1.0", "Reserved values are exclusions inside an otherwise valid numeric range.")
C("An eight-character lowercase ASCII hexadecimal token must include at least one letter a through f, and cannot be all f characters. No separators.",r"(?=.*[a-f])(?!ffffffff$)[0-9a-f]{8}","a0000000|0000000f|abcdef12|deadbeef|fffffffe|f0000000|12ab3456|9999999a","00000000|12345678|ffffffff|a000000|a00000000|A0000000|g0000000", "The letter-presence rule and all-f sentinel are independent.")
search("Search for a lowercase ASCII name 3 to 8 letters immediately between name= and semicolon, excluding the exact names tmp and null. Other text may be anything.","name=",r"(?!tmp;|null;)[a-z]{3,8}",["abc","xyz","abcdefgh","tmpx","nulls","label","sample","value"],";",["tmp","null","ab","abcdefghi","ABC","ab1","ab_","abé"])
C("Search arbitrary text for the lowercase token allow when immediately preceded by colon but not by deny: (the five characters immediately before allow). It must be followed by semicolon. Other occurrences or surrounding text do not matter.",r"(?<=:)(?<!deny:)allow(?=;)","x:allow;|:allow;|okay:allow;|before x:allow; after|denyx:allow;|Deny:allow;|a\n:allow;\nb|deny:allow; x:allow;","deny:allow;|allow;|x:allow |x:Allow;|x:allows;|x:allow|deny:allow; deny:allow;|x: allow;", "A negative left context applies per occurrence, not to the entire document.",contains=True)
C("A whitespace-free task key is 4 to 16 lowercase ASCII letters, digits or underscores, must start with a letter, and must not contain __, end in underscore, or be exactly none.",r"(?!none$)(?!.*__)(?=[a-z0-9_]{4,16}$)[a-z][a-z0-9_]*[a-z0-9]","abcd|a_bc|a1_2|abcdefghijklmnop|none1|foo_bar|x123|a_b_c_d_e_f_g_h1","none|ab__c|abc_|abc|abcdefghijklmnopq|1abc|Abcd|ab-c", "Length and endpoint checks do not enforce the exact exclusions.")
C("A pair record is two different lowercase ASCII words 3 to 8 letters separated by slash. Neither word may be root or null. No spaces or other text.",r"(?!root\/|null\/)([a-z]{3,8})\/(?!\1$|root$|null$)[a-z]{3,8}","abc/xyz|xyz/abc|abcdefgh/value|roots/nulls|foo/bar|left/right|one/two|name/label","abc/abc|root/abc|abc/root|null/abc|abc/null|ab/xyz|abc/abcdefghi|ABC/xyz", "Exact exclusions and equality must be checked on both fields.")
C("A six-digit ASCII control code starts nonzero, has no adjacent repeated digit, and must not contain the substring 123 anywhere. No checksum or other characters.",r"(?!.*123)(?![0-9]*([0-9])\1)[1-9][0-9]{5}","102345|987654|101010|909090|246810|135790|120345|543210","012345|112345|122345|102344|123456|991234|10123|1023456|10234a", "Adjacent repeats and a multi-digit forbidden substring are independent.")
C("An international alias contains 4 through 12 Unicode letters, includes uppercase and lowercase letters, has no adjacent identical code points, and must not contain any ASCII digit or combining mark. No normalization, spaces or other characters.",r"(?=.{4,12}$)(?=.*\p{Lu})(?=.*\p{Ll})(?!.*(\p{L})\1)\p{L}+","Abcd|ÉtéA|ΑβΓδ|Зима|ÅaÅa|Abcdefghijkl|Łódź|Naïve","ABCD|abcd|Abc|Abcdefghijklm|AbbC|AééB|Ab1c|éAbc|Ab c", "Case categories and exact adjacent equality apply across scripts.","u")
envelope("A quarantined note is entirely enclosed in SAFE{ and }SAFE. Its interior is 1 to 40 Unicode code points, allows any characters and newlines, contains the lowercase substring clean, and does not contain the lowercase substring virus.","SAFE{","}SAFE","clean")
# Add the explicit exclusion to the independently authored capsule and its probes.
import author
author.CASES[-1]["regex"] = author.CASES[-1]["regex"].replace(
    ":(?=.{1,40}", r":(?!.*virus.*:\k<route>\}SAFE$)(?=.{1,40}")
author.CASES[-1]["description"] += " The body must not contain the lowercase substring virus."
author.CASES[-1]["no_match"] += ["SAFE{aa:cleanvirus:aa}SAFE", "SAFE{aa:virus\nclean:aa}SAFE"]
author.CASES[-1]["match"] += ["SAFE{virus:clean:virus}SAFE"]
line_copy("An LF-only exclusion receipt has key= followed by 3 to 8 lowercase ASCII letters other than root or null, then copy= and the exact same word. No final LF or spaces.","key=",r"(?!root(?:\n|$)|null(?:\n|$))[a-z]{3,8}",["abc","xyz","abcdefgh","roots","nulls","label","sample","value"])
C("A namespaced selector has three lowercase ASCII words 3 through 8 letters joined by colons. All three must differ; none may be root. No spaces or other characters.",r"(?!root:)([a-z]{3,8}):(?!\1:|root:)([a-z]{3,8}):(?!\1$|\2$|root$)[a-z]{3,8}","one:two:three|red:blue:green|alpha:beta:gamma|abc:def:ghi|roots:rooted:router|foo:bar:baz|north:south:east|left:right:center","one:one:three|one:two:one|one:two:two|root:two:three|one:root:three|one:two:root|on:two:three|one:two:abcdefghi", "All pairings and every reserved-word position must be checked.")
C("A custom multiline record is START, LF, then 1 to 3 lines of 3 to 8 lowercase ASCII letters, LF, and END. None of the interior lines may be exactly skip or stop, and no two interior lines may be identical. No final LF, CR or whitespace.",r"(?![\s\S]*(?:^|\n)([a-z]{3,8})\n(?:[a-z]{3,8}\n)*\1\n)START\n(?!skip\n|stop\n)[a-z]{3,8}\n(?:(?!skip\n|stop\n)[a-z]{3,8}\n){0,2}END","START\nabc\nEND|START\nabcdefgh\nEND|START\none\ntwo\nEND|START\nred\nblue\ngreen\nEND|START\nskips\nEND|START\nstops\nEND|START\nfoo\nbar\nEND|START\nleft\nright\ncenter\nEND","START\nskip\nEND|START\nstop\nEND|START\none\nskip\nEND|START\none\ntwo\nstop\nEND|START\none\ntwo\none\nEND|START\none\none\nEND|START\nEND|START\none\ntwo\nthree\nfour\nEND|START\nab\nEND|START\nabcdefghi\nEND", "Reserved lines and nonadjacent duplicate lines are independent exclusions.")
